/** Compiler-private admitted media for the approval presentation. */
import { createHash } from "node:crypto";

export const approvalVisualAssetRegistry = {
  key: "approval-visual-assets",
  version: "1.0.0",
  ownership: "factory-authored",
  license: "UNLICENSED",
  assets: ["approval-workspace-material", "approval-expense-material"],
} as const;

type StructuralField = {
  readonly key: string;
  readonly type: string;
  readonly required?: boolean;
  readonly values?: readonly string[];
};

export type ApprovalVisualAssetKey =
  "approval-workspace-material" | "approval-expense-material";

export type ApprovalVisualAsset = {
  readonly key: ApprovalVisualAssetKey;
  readonly mediaType: "image/webp";
  readonly width: 768;
  readonly height: 512;
  readonly byteLength: number;
  readonly sha256: string;
  readonly role: "family-hero" | "expense-record";
  readonly provenance: "factory-authored-original";
  readonly license: "UNLICENSED";
  readonly base64: string;
};

export const approvalVisualAssets: Readonly<
  Record<ApprovalVisualAssetKey, ApprovalVisualAsset>
> = {
  "approval-workspace-material": {
    key: "approval-workspace-material",
    mediaType: "image/webp",
    width: 768,
    height: 512,
    byteLength: 26830,
    sha256: "6621d5c80cee5784e8e0920e34c090eb31084f4218d61c7a2e38566712b6a715",
    role: "family-hero",
    provenance: "factory-authored-original",
    license: "UNLICENSED",
    base64:
      "",
  },
  "approval-expense-material": {
    key: "approval-expense-material",
    mediaType: "image/webp",
    width: 768,
    height: 512,
    byteLength: 29056,
    sha256: "c1961dabf8ce08922808dc7f9572bcd1bef57dc95625852d6c65f33097e4d343",
    role: "expense-record",
    provenance: "factory-authored-original",
    license: "UNLICENSED",
    base64:
      "",
  },
};

const expectedKeys: readonly ApprovalVisualAssetKey[] = [
  "approval-workspace-material",
  "approval-expense-material",
];

const expenseSignature: readonly StructuralField[] = [
  { key: "amount", type: "decimal", required: true },
  {
    key: "category",
    type: "enum",
    required: true,
    values: ["travel", "meals", "software", "office", "other"],
  },
  { key: "date", type: "date", required: true },
  { key: "receipt", type: "url", required: false },
  { key: "notes", type: "text", required: false },
  {
    key: "status",
    type: "enum",
    required: true,
    values: ["draft", "submitted", "approved", "rejected"],
  },
];

const purchaseSignature: readonly StructuralField[] = [
  { key: "amount", type: "decimal", required: true },
  {
    key: "category",
    type: "enum",
    required: true,
    values: ["equipment", "software", "services", "supplies", "other"],
  },
  { key: "neededBy", type: "date", required: true },
  { key: "item", type: "string", required: true },
  { key: "supplier", type: "string", required: false },
  { key: "businessJustification", type: "text", required: true },
  {
    key: "status",
    type: "enum",
    required: true,
    values: ["draft", "submitted", "approved", "rejected"],
  },
];

function equalField(
  field: StructuralField,
  expected: StructuralField,
): boolean {
  return (
    field.key === expected.key &&
    field.type === expected.type &&
    Boolean(field.required) === Boolean(expected.required) &&
    JSON.stringify(field.values ?? []) === JSON.stringify(expected.values ?? [])
  );
}

function matchesSignature(
  fields: readonly StructuralField[],
  signature: readonly StructuralField[],
): boolean {
  if (fields.length !== signature.length) return false;
  const remaining = [...fields];
  for (const expected of signature) {
    const index = remaining.findIndex((field) => equalField(field, expected));
    if (index === -1) return false;
    remaining.splice(index, 1);
  }
  return remaining.length === 0;
}

function webpDimensions(bytes: Buffer): readonly [number, number] {
  if (
    bytes.length < 30 ||
    bytes.subarray(0, 4).toString("ascii") !== "RIFF" ||
    bytes.subarray(8, 12).toString("ascii") !== "WEBP" ||
    bytes.readUInt32LE(4) + 8 !== bytes.length
  ) {
    throw new Error("Approval visual asset is not a canonical WebP.");
  }

  let offset = 12;
  let dimensions: readonly [number, number] | undefined;
  while (offset < bytes.length) {
    if (offset + 8 > bytes.length) {
      throw new Error("Approval visual asset has an invalid WebP chunk.");
    }
    const kind = bytes.subarray(offset, offset + 4).toString("ascii");
    const size = bytes.readUInt32LE(offset + 4);
    const body = offset + 8;
    const end = body + size;
    if (end > bytes.length) {
      throw new Error("Approval visual asset has an invalid WebP chunk.");
    }
    if (["EXIF", "XMP ", "ICCP", "ANIM", "ANMF"].includes(kind)) {
      throw new Error("Approval visual asset carries forbidden metadata.");
    }
    if (kind === "VP8 ") {
      if (
        size < 10 ||
        bytes[body + 3] !== 0x9d ||
        bytes[body + 4] !== 0x01 ||
        bytes[body + 5] !== 0x2a
      ) {
        throw new Error("Approval visual asset has an invalid WebP frame.");
      }
      dimensions = [
        bytes.readUInt16LE(body + 6) & 0x3fff,
        bytes.readUInt16LE(body + 8) & 0x3fff,
      ];
    } else if (kind === "VP8X") {
      if (size < 10 || (bytes[body] & 0x02) !== 0) {
        throw new Error("Approval visual asset has an invalid WebP frame.");
      }
      dimensions = [
        1 + bytes[body + 4] + (bytes[body + 5] << 8) + (bytes[body + 6] << 16),
        1 + bytes[body + 7] + (bytes[body + 8] << 8) + (bytes[body + 9] << 16),
      ];
    }
    offset = end + (size % 2);
  }
  if (offset !== bytes.length || !dimensions) {
    throw new Error("Approval visual asset has no image dimensions.");
  }
  return dimensions;
}

export function validateApprovalVisualAssets(
  assets: Readonly<Record<ApprovalVisualAssetKey, ApprovalVisualAsset>>,
): void {
  if (JSON.stringify(Object.keys(assets)) !== JSON.stringify(expectedKeys)) {
    throw new Error("Approval visual asset keys are invalid.");
  }
  for (const key of expectedKeys) {
    const asset = assets[key];
    const bytes = Buffer.from(asset.base64, "base64");
    if (
      JSON.stringify(Object.keys(asset).sort()) !==
        JSON.stringify([
          "base64",
          "byteLength",
          "height",
          "key",
          "license",
          "mediaType",
          "provenance",
          "role",
          "sha256",
          "width",
        ]) ||
      asset.key !== key ||
      asset.role !==
        (key === "approval-workspace-material"
          ? "family-hero"
          : "expense-record") ||
      asset.width !== 768 ||
      asset.height !== 512 ||
      asset.sha256 !==
        (key === "approval-workspace-material"
          ? "6621d5c80cee5784e8e0920e34c090eb31084f4218d61c7a2e38566712b6a715"
          : "c1961dabf8ce08922808dc7f9572bcd1bef57dc95625852d6c65f33097e4d343") ||
      asset.mediaType !== "image/webp" ||
      !/^[A-Za-z0-9+/]+={0,2}$/.test(asset.base64) ||
      Buffer.from(asset.base64, "base64").toString("base64") !== asset.base64 ||
      asset.byteLength !== bytes.byteLength ||
      asset.byteLength >
        (key === "approval-workspace-material" ? 96 * 1024 : 64 * 1024) ||
      createHash("sha256").update(bytes).digest("hex") !== asset.sha256 ||
      asset.provenance !== "factory-authored-original" ||
      asset.license !== "UNLICENSED"
    ) {
      throw new Error("Approval visual asset integrity check failed.");
    }
    const [width, height] = webpDimensions(bytes);
    if (width !== asset.width || height !== asset.height) {
      throw new Error("Approval visual asset dimensions are invalid.");
    }
  }
}

export function approvalVisualDataUrl(asset: ApprovalVisualAsset): string {
  validateApprovalVisualAssets(approvalVisualAssets);
  return `data:${asset.mediaType};base64,${asset.base64}`;
}

export function selectApprovalRecordMaterial(
  fields: readonly StructuralField[],
  correction = false,
): ApprovalVisualAssetKey | undefined {
  const signature = (value: readonly StructuralField[]) =>
    correction
      ? value.map((field) =>
          field.key === "status"
            ? {
                ...field,
                values: ["draft", "submitted", "approved", "returned"],
              }
            : field,
        )
      : value;
  if (matchesSignature(fields, signature(expenseSignature))) {
    return "approval-expense-material";
  }
  if (matchesSignature(fields, signature(purchaseSignature))) {
    return "approval-workspace-material";
  }
  return undefined;
}

validateApprovalVisualAssets(approvalVisualAssets);

